-- Isolated V7 authorization/transaction assertions; never execute against live data.
set role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',false);
select test_assert('Course Lead sees only own authoring courses',jsonb_array_length(get_my_rizsim_course_authoring())=1);
select test_assert('Authoring read excludes session and result data',not(get_my_rizsim_course_authoring('20000000-0000-4000-8000-000000000001') ?| array['sessions','results']));
select test_assert('Authoring returns a revision',length(get_my_rizsim_course_authoring('20000000-0000-4000-8000-000000000001')->>'revision')=32);
select test_reject('Foreign owned course is denied',$q$select get_my_rizsim_course_authoring('20000000-0000-4000-8000-000000000002')$q$,'Course not found');
select test_reject('Open-session course cannot be deleted',$q$select delete_my_rizsim_course_authoring('20000000-0000-4000-8000-000000000001',get_my_rizsim_course_authoring('20000000-0000-4000-8000-000000000001')->>'revision')$q$,'open sessions');
select prepare_rizsim_course_authoring('70000000-0000-4000-8000-000000000001');
select test_assert('New course is not created merely for an upload reservation',jsonb_array_length(get_my_rizsim_course_authoring())=1);
select test_assert('Staged file path is owned and bound to reserved course',rizsim_authoring_upload_path('70000000-0000-4000-8000-000000000001/authoring/10000000-0000-4000-8000-000000000001/80000000-0000-4000-8000-000000000001/handout.pdf'));
select test_assert('Staged path traversal denied',not rizsim_authoring_upload_path('70000000-0000-4000-8000-000000000001/authoring/10000000-0000-4000-8000-000000000001/80000000-0000-4000-8000-000000000001/../handout.pdf'));
select test_assert('Staged foreign user path denied',not rizsim_authoring_upload_path('70000000-0000-4000-8000-000000000001/authoring/10000000-0000-4000-8000-000000000002/80000000-0000-4000-8000-000000000001/handout.pdf'));
select test_assert('Existing session prefix is not granted by authoring',not rizsim_authoring_upload_path('sessions/50000000-0000-4000-8000-000000000002/file.pdf'));
insert into storage.objects(bucket_id,name) values('course-materials','70000000-0000-4000-8000-000000000001/authoring/10000000-0000-4000-8000-000000000001/80000000-0000-4000-8000-000000000001/handout.pdf');
select save_my_rizsim_course_authoring('70000000-0000-4000-8000-000000000001','90000000-0000-4000-8000-000000000001',null,
'{"title":"Authored course","description":"Saved atomically","simulations":["30000000-0000-4000-8000-000000000001"],"keep_resources":[],"new_resources":[{"id":"80000000-0000-4000-8000-000000000001","title":"Saved handout","source_type":"file","material_type":"reading","storage_path":"70000000-0000-4000-8000-000000000001/authoring/10000000-0000-4000-8000-000000000001/80000000-0000-4000-8000-000000000001/handout.pdf","mime_type":"application/pdf","file_name":"handout.pdf","file_size":30},{"id":"80000000-0000-4000-8000-000000000002","title":"Web reading","source_type":"link","material_type":"external_link","external_url":"https://example.org/reading"}]}');
select test_assert('Complete course created once',jsonb_array_length(get_my_rizsim_course_authoring())=2);
select test_assert('Both file and link retained',jsonb_array_length(get_my_rizsim_course_authoring('70000000-0000-4000-8000-000000000001')->'resources')=2);
select test_assert('New authoring resources remain private',not exists(select 1 from jsonb_array_elements(get_my_rizsim_course_authoring('70000000-0000-4000-8000-000000000001')->'resources')r where (r->>'published_to_class')::boolean));
select test_reject('Changed payload cannot reuse a save receipt',$q$select save_my_rizsim_course_authoring('70000000-0000-4000-8000-000000000001','90000000-0000-4000-8000-000000000001',null,'{"title":"Different","simulations":[],"keep_resources":[],"new_resources":[]}')$q$,'save request has changed');
select test_reject('Missing file rolls back entire new course',$q$select save_my_rizsim_course_authoring('70000000-0000-4000-8000-000000000009','90000000-0000-4000-8000-000000000009',null,'{"title":"Must not appear","simulations":[],"keep_resources":[],"new_resources":[{"id":"80000000-0000-4000-8000-000000000009","title":"Bad file","material_type":"reading","source_type":"file","storage_path":"foreign/file.pdf","file_size":10,"mime_type":"application/pdf","file_name":"x.pdf"}]}')$q$,'authorized upload scope');
select test_assert('Rejected save created no partial course',jsonb_array_length(get_my_rizsim_course_authoring())=2);
select test_reject('New unlicensed simulation rejected',$q$select save_my_rizsim_course_authoring('70000000-0000-4000-8000-000000000009','90000000-0000-4000-8000-000000000008',null,'{"title":"Unlicensed course","simulations":["30000000-0000-4000-8000-000000000002"],"keep_resources":[],"new_resources":[]}')$q$,'active simulation licence');
select test_reject('Duplicate simulation IDs rejected',$q$select save_my_rizsim_course_authoring('70000000-0000-4000-8000-000000000009','90000000-0000-4000-8000-000000000007',null,'{"title":"Duplicate course","simulations":["30000000-0000-4000-8000-000000000001","30000000-0000-4000-8000-000000000001"],"keep_resources":[],"new_resources":[]}')$q$,'Duplicate');
select test_reject('Forged retained resource rejected',$q$select save_my_rizsim_course_authoring('70000000-0000-4000-8000-000000000009','90000000-0000-4000-8000-000000000006',null,'{"title":"Bad keep","simulations":[],"keep_resources":["60000000-0000-4000-8000-000000000002"],"new_resources":[]}')$q$,'resource does not belong');
select test_reject('Stale editor cannot overwrite another save',$q$select save_my_rizsim_course_authoring('70000000-0000-4000-8000-000000000001','90000000-0000-4000-8000-000000000005','stale','{"title":"Stale title","simulations":[],"keep_resources":[],"new_resources":[]}')$q$,'changed in another workspace');
select test_reject('Script URL rejected on server',$q$select save_my_rizsim_course_authoring('70000000-0000-4000-8000-000000000009','90000000-0000-4000-8000-000000000004',null,'{"title":"Bad URL course","simulations":[],"keep_resources":[],"new_resources":[{"id":"80000000-0000-4000-8000-000000000009","title":"Bad URL","material_type":"reading","source_type":"link","external_url":"javascript:alert(1)"}]}')$q$,'valid http or https');
select test_reject('Cannot remove an open-session simulation',$q$select save_my_rizsim_course_authoring('20000000-0000-4000-8000-000000000001','90000000-0000-4000-8000-000000000003',get_my_rizsim_course_authoring('20000000-0000-4000-8000-000000000001')->>'revision','{"title":"Same course","simulations":[],"keep_resources":["60000000-0000-4000-8000-000000000001"],"new_resources":[]}')$q$,'open course session');
select save_my_rizsim_course_authoring('70000000-0000-4000-8000-000000000001','90000000-0000-4000-8000-000000000011',get_my_rizsim_course_authoring('70000000-0000-4000-8000-000000000001')->>'revision','{"title":"Revised course","simulations":["30000000-0000-4000-8000-000000000001"],"keep_resources":["80000000-0000-4000-8000-000000000001"],"new_resources":[]}');
select test_assert('Title edits persist',get_my_rizsim_course_authoring('70000000-0000-4000-8000-000000000001')->>'title'='Revised course');
select test_assert('Removed resource no longer in authoring list',jsonb_array_length(get_my_rizsim_course_authoring('70000000-0000-4000-8000-000000000001')->'resources')=1);
select delete_my_rizsim_course_authoring('70000000-0000-4000-8000-000000000001',get_my_rizsim_course_authoring('70000000-0000-4000-8000-000000000001')->>'revision');
select test_assert('Deleted course disappears without deleting legacy course',jsonb_array_length(get_my_rizsim_course_authoring())=1);
select test_assert('Delete retry is idempotent',(delete_my_rizsim_course_authoring('70000000-0000-4000-8000-000000000001','old')->>'deleted')::boolean);
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000002',false);
select test_reject('Ordinary Faculty cannot author',$q$select get_my_rizsim_course_authoring()$q$,'Course Lead');
select test_reject('Ordinary Faculty cannot reserve upload',$q$select prepare_rizsim_course_authoring('70000000-0000-4000-8000-000000000099')$q$,'Course Lead');
select test_assert('Other user cannot read save receipts',(select count(*) from rizsim_course_authoring_receipts)=0);
select test_assert('Other user cannot read upload tickets',(select count(*) from rizsim_course_authoring_uploads)=0);
reset role;
select test_assert('Existing session and attempt records unchanged',(select count(*) from classroom_sessions)=2 and (select count(*) from simulation_attempts)=2);
select test_assert('Deleted resources remain stored',(select count(*) from rizsim_course_materials where course_id='70000000-0000-4000-8000-000000000001')=2);
select test_assert('Deleted course record retained for history',exists(select 1 from rizsim_courses where id='70000000-0000-4000-8000-000000000001' and not active and authoring_deleted));
select test_assert('Public role cannot execute authoring API',not has_function_privilege('anon','public.save_my_rizsim_course_authoring(uuid,uuid,text,jsonb)','EXECUTE'));
select test_assert('No direct client writes to save receipts',not has_table_privilege('authenticated','public.rizsim_course_authoring_receipts','INSERT,UPDATE,DELETE'));
select test_assert('New authoring tables both use RLS',(select bool_and(relrowsecurity) from pg_class where oid in ('public.rizsim_course_authoring_uploads'::regclass,'public.rizsim_course_authoring_receipts'::regclass)));
